// --- Syscall Interaction (Write) ---
#define STDOUT_FILENO 1

// Syscall requests kernel service
char buffer[] = "Requesting IO...\n";
ssize_t count = sizeof(buffer) - 1;

// Blocking call transitions to kernel mode
ssize_t written = write(STDOUT_FILENO, buffer, count);

// Check errno on error (return < 0)
if (written < 0) {
    // Syscall failed
}


// --- Exceptional Control Flow (Signals) ---
// Asynchronous software interruption

void sig_handler(int sig) {
    // Kernel interrupted normal flow to run handler
    // Must use async-signal-safe functions
    _exit(1); 
}

struct sigaction sa;
sa.sa_handler = sig_handler;
sigemptyset(&sa.sa_mask);
sa.sa_flags = SA_RESTART; // Resume blocked syscalls

// Register handler for SIGINT (Ctrl+C)
sigaction(SIGINT, &sa, NULL);

// Triggering ECF manually
raise(SIGINT);
// Program counter jumps to sig_handler
// Kernel handles context switch (User -> Kernel -> User Handler)
